select ac_cargar_unidad($ac${"slug":"comunidad-1","rama":"comunidad","orden":1,"nivel":1,"titulo_es":"Del yo al nosotros","bajada_es":"Lo que hacés vos importa, y lo que hacemos juntos importa todavía más. Cómo se contagian los hábitos, cómo se organiza un barrio y cómo sostener la esperanza.","objetivos_es":["Distinguir los problemas que se resuelven individualmente de los que requieren acción colectiva","Explicar cómo las normas sociales y el ejemplo contagian comportamientos","Planificar un proyecto ambiental comunitario paso a paso","Aplicar estrategias de comunicación que suman personas","Reconocer la ecoansiedad y formas saludables de afrontarla"],"repasa":["tronco-3"],"requiere_tronco":1,"fuentes":["bit-east","lally-2010-habitos","ecoansiedad-review","onu-ods","naaee-guidelines"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"comunidad-1.s1","orden":1,"tipo":"leccion","titulo_es":"Lo que puedo solo y lo que hacemos juntos","bajada_es":"La tragedia de los comunes, los bienes compartidos y por qué algunos problemas no tienen solución individual.","minutos":11,"pasos":[{"slug":"comunidad-1.s1.p1","orden":1,"grupo":"comunidad-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los bienes comunes","cuerpo":["Hay recursos que son de todos y de nadie a la vez: el aire, un río, un banco de peces, una plaza. Si cada persona usa un poco más de lo que le corresponde, pensando que su parte no cambia nada, entre todos el recurso se agota. A eso se lo llamó \"la tragedia de los comunes\".","Pero la historia muestra que muchas comunidades lograron cuidar sus bienes comunes durante siglos, con reglas acordadas, control mutuo y sanciones justas. La politóloga Elinor Ostrom ganó el Premio Nobel de Economía en 2009 por estudiar cómo lo hacen."]},"solucion":{}},{"slug":"comunidad-1.s1.p2","orden":2,"grupo":"comunidad-1.s1.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una tragedia de los comunes en una laguna de pesca.","items":[{"id":"i1","texto":"Cada pescador piensa que sacar un poco más no cambia nada"},{"id":"i2","texto":"Todos sacan un poco más"},{"id":"i3","texto":"Los peces no alcanzan a reproducirse"},{"id":"i4","texto":"La población de peces se derrumba"},{"id":"i5","texto":"Todos los pescadores pierden"},{"id":"i6","texto":"Los peces se multiplican más cuanto más se pesca"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo que tiene sentido para cada uno por separado termina mal para todos. Por eso los bienes comunes necesitan acuerdos."}},{"slug":"comunidad-1.s1.p3","orden":3,"grupo":"comunidad-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se cuidan los comunes","cuerpo":["Ostrom encontró que las comunidades que cuidan bien sus bienes comunes suelen tener algunas cosas en común: límites claros de quién usa el recurso, reglas adaptadas al lugar, participación de los usuarios en fijar las reglas, vigilancia, sanciones graduales y formas baratas de resolver conflictos."]},"solucion":{}},{"slug":"comunidad-1.s1.p4","orden":4,"grupo":"comunidad-1.s1.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a una comunidad a cuidar un bien común? Marcá todo.","opciones":[{"id":"o1","texto":"Reglas acordadas por quienes usan el recurso"},{"id":"o2","texto":"Vigilar que se cumplan"},{"id":"o3","texto":"Sanciones graduales y justas"},{"id":"o4","texto":"Formas de resolver conflictos"},{"id":"o5","texto":"Que cada uno haga lo que quiera sin hablar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Acuerdos, control y justicia: la receta que Ostrom encontró en comunidades de todo el mundo."}},{"slug":"comunidad-1.s1.p5","orden":5,"grupo":"comunidad-1.s1.p5","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este problema se resuelve sobre todo con acción individual o necesita acción colectiva?","grupos":[{"id":"g1","nombre":"Sobre todo individual"},{"id":"g2","nombre":"Necesita acción colectiva"}],"items":[{"id":"i1","texto":"Apagar las luces de tu cuarto"},{"id":"i2","texto":"Que haya recolección diferenciada en el barrio"},{"id":"i3","texto":"Llevar tu bolsa a las compras"},{"id":"i4","texto":"Limpiar y proteger un arroyo"},{"id":"i5","texto":"Reparar tu bicicleta"},{"id":"i6","texto":"Que la ciudad tenga ciclovías conectadas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas soluciones necesitan las dos cosas: tu hábito y un sistema que lo haga posible. Es lo tuyo y lo de todos del tronco."}},{"slug":"comunidad-1.s1.p6","orden":6,"grupo":"comunidad-1.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un problema es colectivo, lo que hace cada persona no importa.","razones":[{"id":"r1","texto":"Porque lo individual suma, contagia y empuja cambios colectivos"},{"id":"r2","texto":"Porque las personas no forman parte de la sociedad"},{"id":"r3","texto":"Porque los problemas colectivos se resuelven solos"}]},"solucion":{"valor":false,"explicacion":"Lo individual suma, da el ejemplo y genera presión para cambiar el sistema. Y los cambios colectivos empiezan por personas que se organizan.","clave":["r1"]}},{"slug":"comunidad-1.s1.p7","orden":7,"grupo":"comunidad-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La trampa del \"no cambia nada\"","cuerpo":["Frente a problemas enormes como el cambio climático, es común pensar \"lo mío no cambia nada\". Pero ese razonamiento, repetido por millones, es justamente lo que produce el problema. Y al revés: los cambios grandes empiezan con grupos chicos que se organizan y convencen a otros."]},"solucion":{}},{"slug":"comunidad-1.s1.p8","orden":8,"grupo":"comunidad-1.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un vecino dice: \"Si yo separo la basura, no cambia nada; somos millones\". ¿Qué respuesta es más acertada?","opciones":[{"id":"o1","texto":"Lo que hace cada uno suma, y además contagia"},{"id":"o2","texto":"Tiene razón, no tiene sentido hacer nada"},{"id":"o3","texto":"Solo importa lo que hace el gobierno"},{"id":"o4","texto":"Hay que separar solo si todos los demás separan primero"}]},"solucion":{"clave":["o1"],"explicacion":"El \"no cambia nada\" repetido por millones es el problema. Lo mismo al revés es la solución.","por_opcion":{"o3":"El gobierno importa mucho, pero los cambios de hábito también suman y empujan las políticas."}}},{"slug":"comunidad-1.s1.p9","orden":9,"grupo":"comunidad-1.s1.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada bien común con una regla que ayuda a cuidarlo.","izquierda":[{"id":"a1","texto":"Laguna de pesca"},{"id":"a2","texto":"Plaza del barrio"},{"id":"a3","texto":"Aire de la ciudad"},{"id":"a4","texto":"Acuífero de un pueblo"}],"derecha":[{"id":"b1","texto":"Talla mínima y temporada de veda"},{"id":"b2","texto":"Turnos para el mantenimiento entre vecinos"},{"id":"b3","texto":"Límites de emisiones para industrias y vehículos"},{"id":"b4","texto":"Registro de pozos y límites de extracción"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada bien común tiene su regla. Las mejores se acuerdan con quienes lo usan."}},{"slug":"comunidad-1.s1.p10","orden":10,"grupo":"comunidad-1.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna pescan 20 personas. Si cada una saca 5 kg más por temporada de lo sustentable, ¿cuántos kg de más se sacan entre todos?","unidad":"kg","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"20 × 5 = 100 kg de más. Poco para cada uno, mucho para la laguna: la lógica de la tragedia de los comunes."}},{"slug":"comunidad-1.s1.p10.v2","orden":10,"grupo":"comunidad-1.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna pescan 30 personas. Si cada una saca 3 kg más por temporada de lo sustentable, ¿cuántos kg de más se sacan entre todos?","unidad":"kg","decimales":0},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"30 × 3 = 90 kg de más. Poco para cada uno, mucho para la laguna: la lógica de la tragedia de los comunes."}},{"slug":"comunidad-1.s1.p10.v3","orden":10,"grupo":"comunidad-1.s1.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna pescan 10 personas. Si cada una saca 10 kg más por temporada de lo sustentable, ¿cuántos kg de más se sacan entre todos?","unidad":"kg","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"10 × 10 = 100 kg de más. Poco para cada uno, mucho para la laguna: la lógica de la tragedia de los comunes."}},{"slug":"comunidad-1.s1.p11","orden":11,"grupo":"comunidad-1.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un pueblo de pescadores, ¿qué medida se parece más a lo que Ostrom encontró que funciona?","opciones":[{"id":"o1","texto":"Que los pescadores acuerden y controlen sus reglas"},{"id":"o2","texto":"Que cada pescador saque todo lo que pueda"},{"id":"o3","texto":"Que alguien de afuera prohíba pescar sin consultar"},{"id":"o4","texto":"Que no haya ninguna regla ni vigilancia"}]},"solucion":{"clave":["o1"],"explicacion":"Cuando quienes usan el recurso participan en fijar y controlar las reglas, las respetan más.","por_opcion":{"o3":"Las reglas impuestas sin participación suelen cumplirse peor; la participación es clave."}}},{"slug":"comunidad-1.s1.p12","orden":12,"grupo":"comunidad-1.s1.p12","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para acordar el cuidado de un bien común.","items":[{"id":"i1","texto":"Reunir a quienes usan el recurso"},{"id":"i2","texto":"Medir cuánto hay y cuánto se usa"},{"id":"i3","texto":"Acordar reglas y límites"},{"id":"i4","texto":"Vigilar que se cumplan"},{"id":"i5","texto":"Revisar las reglas según los resultados"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Reunir, medir, acordar, controlar y ajustar: el ciclo de un bien común bien cuidado."}},{"slug":"comunidad-1.s1.p13","orden":13,"grupo":"comunidad-1.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta discusión vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La plaza es de todos, así que tenemos que acordar cómo cuidarla."},{"id":"s2","texto":"Como la plaza es de todos, a nadie le toca cuidarla."},{"id":"s3","texto":"Podemos organizar turnos para regar los canteros."},{"id":"s4","texto":"Las comunidades nunca logran cuidar sus bienes comunes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo común necesita acuerdos, no abandono.","por_opcion":{"s2":"Es justamente lo que lleva a la tragedia de los comunes.","s4":"Muchas lo lograron durante siglos, como mostró Elinor Ostrom."}}},{"slug":"comunidad-1.s1.p14","orden":14,"grupo":"comunidad-1.s1.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando cada uno usa de más un recurso compartido y se agota, se habla de la tragedia de los {{0}}; Elinor {{1}} estudió cómo las comunidades los cuidan.","banco":[{"id":"w1","texto":"comunes"},{"id":"w2","texto":"Ostrom"},{"id":"w3","texto":"privados"},{"id":"w4","texto":"Montreal"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Un problema clásico de los bienes compartidos y su respuesta."}}]},{"slug":"comunidad-1.s2","orden":2,"tipo":"leccion","titulo_es":"Los hábitos se contagian","bajada_es":"Normas sociales, ejemplo y visibilidad: por qué hacemos lo que vemos hacer.","minutos":11,"pasos":[{"slug":"comunidad-1.s2.p1","orden":1,"grupo":"comunidad-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Normas sociales","cuerpo":["Las personas se guían mucho por lo que hacen los demás. Una norma social descriptiva es lo que la gente efectivamente hace (\"en este barrio casi todos separan la basura\"). Una norma prescriptiva es lo que se considera correcto (\"hay que separar la basura\").","Las investigaciones sobre comportamiento muestran que saber que otros ya hacen algo aumenta la probabilidad de hacerlo. Por eso, un mensaje como \"la mayoría de tus vecinos ya ahorra agua\" suele funcionar mejor que \"hay que ahorrar agua\"."]},"solucion":{}},{"slug":"comunidad-1.s2.p2","orden":2,"grupo":"comunidad-1.s2.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué mensaje tiene más probabilidades de que los vecinos separen la basura?","opciones":[{"id":"o1","texto":"\"7 de cada 10 vecinos de esta cuadra ya separan\""},{"id":"o2","texto":"\"Muy pocos vecinos separan la basura\""},{"id":"o3","texto":"\"Separar es obligatorio por ordenanza\""},{"id":"o4","texto":"\"La basura es un desastre en este barrio\""}]},"solucion":{"clave":["o1"],"explicacion":"Mostrar que la mayoría ya lo hace invita a sumarse. Decir que \"casi nadie lo hace\" puede tener el efecto contrario.","por_opcion":{"o3":"Las reglas importan, pero mostrar que otros ya lo hacen suele motivar más."}}},{"slug":"comunidad-1.s2.p3","orden":3,"grupo":"comunidad-1.s2.p3","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un mensaje que dice \"casi nadie recicla en este barrio\" motiva a reciclar más.","razones":[{"id":"r1","texto":"Porque muestra que lo normal es no hacerlo"},{"id":"r2","texto":"Porque las personas nunca se fijan en los demás"},{"id":"r3","texto":"Porque los mensajes negativos siempre funcionan mejor"}]},"solucion":{"valor":false,"explicacion":"Puede tener el efecto contrario: muestra que lo normal es no reciclar. Es mejor destacar a quienes sí lo hacen.","clave":["r1"]}},{"slug":"comunidad-1.s2.p4","orden":4,"grupo":"comunidad-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo visible se contagia","cuerpo":["Los comportamientos que se ven se contagian más. Estudios en distintos países encontraron que cuando una casa instala paneles solares, aumenta la probabilidad de que los vecinos cercanos también los instalen. Lo mismo pasa con las huertas, las bicis o las composteras visibles.","Por eso, hacer visible lo que ya se hace —un cartel en la compostera, una huerta en el frente— es una forma de sumar."]},"solucion":{}},{"slug":"comunidad-1.s2.p5","orden":5,"grupo":"comunidad-1.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una huerta en el frente de una casa puede contagiar a la cuadra.","items":[{"id":"i1","texto":"Una familia arma una huerta en el frente"},{"id":"i2","texto":"Los vecinos la ven todos los días"},{"id":"i3","texto":"Algunos preguntan cómo hacerla"},{"id":"i4","texto":"La familia comparte semillas y consejos"},{"id":"i5","texto":"Aparecen más huertas en la cuadra"},{"id":"i6","texto":"La huerta obliga a los vecinos a plantar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ejemplo visible y la ayuda concreta son una combinación poderosa."}},{"slug":"comunidad-1.s2.p6","orden":6,"grupo":"comunidad-1.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hacerlo fácil, atractivo, social y oportuno","cuerpo":["Un marco muy usado para diseñar cambios de comportamiento, del equipo británico de ciencias del comportamiento, se resume en cuatro palabras: fácil, atractivo, social y oportuno. Si algo es fácil de hacer, llama la atención, otros lo hacen y se propone en el momento justo, es mucho más probable que ocurra."],"lista":["Fácil: sacar obstáculos","Atractivo: que llame la atención","Social: mostrar que otros lo hacen","Oportuno: en el momento justo"]},"solucion":{}},{"slug":"comunidad-1.s2.p7","orden":7,"grupo":"comunidad-1.s2.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada principio con un ejemplo.","izquierda":[{"id":"a1","texto":"Fácil"},{"id":"a2","texto":"Atractivo"},{"id":"a3","texto":"Social"},{"id":"a4","texto":"Oportuno"}],"derecha":[{"id":"b1","texto":"Poner el tacho de reciclables al lado del de basura"},{"id":"b2","texto":"Un cartel colorido con un dibujo claro"},{"id":"b3","texto":"Mostrar cuántos vecinos ya participan"},{"id":"b4","texto":"Invitar a compostar justo cuando llega la primavera"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palancas que cualquier proyecto comunitario puede usar."}},{"slug":"comunidad-1.s2.p8","orden":8,"grupo":"comunidad-1.s2.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida hace más fácil el comportamiento buscado o más difícil?","grupos":[{"id":"g1","nombre":"Más fácil"},{"id":"g2","nombre":"Más difícil"}],"items":[{"id":"i1","texto":"Bicicletero en la puerta de la escuela"},{"id":"i2","texto":"Tacho de reciclables en el sótano sin luz"},{"id":"i3","texto":"Bebedero junto al kiosco"},{"id":"i4","texto":"Formulario de diez páginas para sumarse a la huerta"},{"id":"i5","texto":"Punto verde en la entrada del súper"},{"id":"i6","texto":"Bicicletero a tres cuadras de la entrada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Muchas veces el obstáculo no es la voluntad sino la fricción. Sacarla es la primera palanca."}},{"slug":"comunidad-1.s2.p9","orden":9,"grupo":"comunidad-1.s2.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un comportamiento se contagie en un barrio? Marcá todo.","opciones":[{"id":"o1","texto":"Que sea visible"},{"id":"o2","texto":"Que alguien cercano lo haga primero"},{"id":"o3","texto":"Que sea fácil de copiar"},{"id":"o4","texto":"Que haya ayuda para empezar"},{"id":"o5","texto":"Que se haga en secreto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Visibilidad, cercanía, facilidad y ayuda: así se contagian los hábitos."}},{"slug":"comunidad-1.s2.p10","orden":10,"grupo":"comunidad-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuadra de 40 casas, el 25 % ya composta. ¿Cuántas casas compostan?","unidad":"casas","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"40 × 25 ÷ 100 = 10 casas. Contarlo en voz alta (\"10 familias de la cuadra ya compostan\") es una norma social que invita a sumarse."}},{"slug":"comunidad-1.s2.p10.v2","orden":10,"grupo":"comunidad-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuadra de 60 casas, el 20 % ya composta. ¿Cuántas casas compostan?","unidad":"casas","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"60 × 20 ÷ 100 = 12 casas. Contarlo en voz alta (\"12 familias de la cuadra ya compostan\") es una norma social que invita a sumarse."}},{"slug":"comunidad-1.s2.p10.v3","orden":10,"grupo":"comunidad-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuadra de 30 casas, el 30 % ya composta. ¿Cuántas casas compostan?","unidad":"casas","decimales":0},"solucion":{"valor":9,"tolerancia":0.5,"explicacion":"30 × 30 ÷ 100 = 9 casas. Contarlo en voz alta (\"9 familias de la cuadra ya compostan\") es una norma social que invita a sumarse."}},{"slug":"comunidad-1.s2.p11","orden":11,"grupo":"comunidad-1.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si algo es fácil de hacer, es más probable que la gente lo haga.","razones":[{"id":"r1","texto":"Porque sacar obstáculos reduce la fricción para actuar"},{"id":"r2","texto":"Porque la gente prefiere siempre lo difícil"},{"id":"r3","texto":"Porque la facilidad no influye en lo que hacemos"}]},"solucion":{"valor":true,"explicacion":"Sacar obstáculos es una de las palancas más efectivas para cambiar comportamientos: muchas veces el problema no es la voluntad, sino la fricción.","clave":["r1"]}},{"slug":"comunidad-1.s2.p12","orden":12,"grupo":"comunidad-1.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una escuela quiere que más chicos traigan su botella reutilizable. ¿Qué medida la hace más fácil?","opciones":[{"id":"o1","texto":"Instalar bebederos para rellenarla"},{"id":"o2","texto":"Dar una charla una vez por año"},{"id":"o3","texto":"Prohibir las botellas descartables sin alternativa"},{"id":"o4","texto":"Pegar un cartel en la dirección"}]},"solucion":{"clave":["o1"],"explicacion":"Si rellenar es fácil, traer la botella se vuelve lo más cómodo.","por_opcion":{"o3":"Sin un lugar para rellenar, la prohibición sola genera rechazo."}}},{"slug":"comunidad-1.s2.p13","orden":13,"grupo":"comunidad-1.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta campaña escolar y marcá lo que puede funcionar mal.","segmentos":[{"id":"s1","texto":"Pondremos tachos de reciclables al lado de cada tacho común."},{"id":"s2","texto":"El afiche dirá: \"Casi nadie en esta escuela recicla\"."},{"id":"s3","texto":"Mostraremos cada mes cuántos kilos se reciclaron."},{"id":"s4","texto":"Los tachos de reciclables estarán solo en la dirección."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Fácil, atractivo, social y oportuno: y cuidado con los mensajes que muestran lo contrario.","por_opcion":{"s2":"Muestra que lo normal es no reciclar; mejor destacar a quienes sí lo hacen.","s4":"Si es difícil, casi nadie lo va a hacer."}}},{"slug":"comunidad-1.s2.p14","orden":14,"grupo":"comunidad-1.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que la gente efectivamente hace es una norma social {{0}}; para que un hábito se contagie conviene que sea {{1}} y fácil.","banco":[{"id":"w1","texto":"descriptiva"},{"id":"w2","texto":"visible"},{"id":"w3","texto":"secreta"},{"id":"w4","texto":"oculto"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para que un comportamiento se contagie."}}]},{"slug":"comunidad-1.s3","orden":3,"tipo":"leccion","titulo_es":"Organizarse en el barrio","bajada_es":"Del problema al proyecto: diagnóstico, objetivo, aliados, plan, acción y evaluación.","minutos":11,"pasos":[{"slug":"comunidad-1.s3.p1","orden":1,"grupo":"comunidad-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De la queja al proyecto","cuerpo":["Muchos problemas ambientales del barrio —un basural en un terreno, una plaza abandonada, un arroyo sucio, falta de árboles— se pueden mejorar con un proyecto comunitario. El camino suele tener varios pasos: entender bien el problema (diagnóstico), elegir un objetivo concreto, sumar aliados, armar un plan, actuar y evaluar lo logrado."]},"solucion":{}},{"slug":"comunidad-1.s3.p2","orden":2,"grupo":"comunidad-1.s3.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de un proyecto comunitario.","items":[{"id":"i1","texto":"Hacer un diagnóstico del problema"},{"id":"i2","texto":"Elegir un objetivo concreto y medible"},{"id":"i3","texto":"Sumar aliados"},{"id":"i4","texto":"Armar un plan con tareas y fechas"},{"id":"i5","texto":"Actuar"},{"id":"i6","texto":"Evaluar y contar los resultados"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Seis pasos que ordenan cualquier proyecto, grande o chico."}},{"slug":"comunidad-1.s3.p3","orden":3,"grupo":"comunidad-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un objetivo concreto","cuerpo":["Un objetivo como \"mejorar el ambiente del barrio\" es demasiado general. Uno concreto dice qué, cuánto, dónde y para cuándo: \"plantar 30 árboles nativos en las veredas de las cuatro cuadras alrededor de la escuela antes de fin de año\".","Los objetivos concretos permiten saber si se logró, organizar las tareas y contar los resultados."]},"solucion":{}},{"slug":"comunidad-1.s3.p4","orden":4,"grupo":"comunidad-1.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estos es el objetivo más concreto?","opciones":[{"id":"o1","texto":"Instalar 3 composteras en la plaza antes de octubre"},{"id":"o2","texto":"Hacer del barrio un lugar más verde y lindo"},{"id":"o3","texto":"Concientizar a todos sobre el ambiente"},{"id":"o4","texto":"Cambiar la forma de pensar de los vecinos"}]},"solucion":{"clave":["o1"],"explicacion":"Qué, cuánto, dónde y para cuándo. Así se puede planificar y evaluar.","por_opcion":{"o3":"Es importante, pero así planteado no se puede medir ni saber cuándo se logró."}}},{"slug":"comunidad-1.s3.p5","orden":5,"grupo":"comunidad-1.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aliados","cuerpo":["Casi ningún proyecto se hace solo. Los aliados pueden ser vecinos, escuelas, clubes, iglesias, comercios, cooperativas, organizaciones ambientales, universidades y el municipio. Cada uno aporta algo: personas, lugar, herramientas, conocimiento, permisos, difusión.","Un buen mapa de aliados pregunta: ¿a quién le importa este problema?, ¿quién puede ayudar?, ¿quién tiene que autorizar?"]},"solucion":{}},{"slug":"comunidad-1.s3.p6","orden":6,"grupo":"comunidad-1.s3.p6","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada aliado con lo que puede aportar a un proyecto de arbolado.","izquierda":[{"id":"a1","texto":"Vivero municipal"},{"id":"a2","texto":"Escuela"},{"id":"a3","texto":"Municipio"},{"id":"a4","texto":"Ferretería del barrio"}],"derecha":[{"id":"b1","texto":"Plantines de nativas"},{"id":"b2","texto":"Estudiantes y un espacio para aprender"},{"id":"b3","texto":"Permisos para plantar en las veredas"},{"id":"b4","texto":"Herramientas prestadas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada aliado suma una pieza distinta. Juntos hacen posible lo que nadie podría solo."}},{"slug":"comunidad-1.s3.p7","orden":7,"grupo":"comunidad-1.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué paso del proyecto es cada acción?","grupos":[{"id":"g1","nombre":"Diagnóstico"},{"id":"g2","nombre":"Plan"},{"id":"g3","nombre":"Evaluación"}],"items":[{"id":"i1","texto":"Contar cuántos árboles faltan en cada cuadra"},{"id":"i2","texto":"Hacer un calendario de plantación"},{"id":"i3","texto":"Contar cuántos árboles sobrevivieron al año"},{"id":"i4","texto":"Preguntar a los vecinos qué problemas ven"},{"id":"i5","texto":"Repartir tareas entre los grupos"},{"id":"i6","texto":"Hacer una encuesta después de la plantación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada etapa tiene sus tareas. Saltarse el diagnóstico o la evaluación es un error común."}},{"slug":"comunidad-1.s3.p8","orden":8,"grupo":"comunidad-1.s3.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Evaluar un proyecto al final es una pérdida de tiempo si ya se hizo la acción.","razones":[{"id":"r1","texto":"Porque muestra qué funcionó y ayuda a sumar apoyo"},{"id":"r2","texto":"Porque los proyectos nunca tienen resultados"},{"id":"r3","texto":"Porque evaluar arruina lo que se hizo"}]},"solucion":{"valor":false,"explicacion":"La evaluación muestra qué funcionó, qué no y qué mejorar. Además, contar los resultados ayuda a sumar más gente y apoyo para el próximo paso.","clave":["r1"]}},{"slug":"comunidad-1.s3.p9","orden":9,"grupo":"comunidad-1.s3.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un proyecto chico puede crecer.","items":[{"id":"i1","texto":"Un grupo de vecinos limpia un terreno y arma una huerta"},{"id":"i2","texto":"Miden y cuentan lo que lograron"},{"id":"i3","texto":"Otros vecinos y la escuela se suman"},{"id":"i4","texto":"El municipio apoya con herramientas y agua"},{"id":"i5","texto":"La huerta se convierte en un espacio comunitario estable"},{"id":"i6","texto":"El proyecto crece solo sin que nadie lo cuente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Empezar chico, mostrar resultados y sumar aliados: el camino de muchos proyectos exitosos."}},{"slug":"comunidad-1.s3.p10","orden":10,"grupo":"comunidad-1.s3.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que un proyecto comunitario dure en el tiempo? Marcá todo.","opciones":[{"id":"o1","texto":"Repartir las tareas entre varias personas"},{"id":"o2","texto":"Tener reuniones periódicas cortas"},{"id":"o3","texto":"Celebrar los logros"},{"id":"o4","texto":"Sumar nuevas personas cada tanto"},{"id":"o5","texto":"Que una sola persona haga todo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Si todo depende de una persona, el proyecto se apaga cuando esa persona se cansa."}},{"slug":"comunidad-1.s3.p11","orden":11,"grupo":"comunidad-1.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto plantó 30 árboles y al año sobrevivieron 24. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"24 ÷ 30 × 100 = 80 %. Medir la supervivencia permite aprender: ¿faltó riego?, ¿se eligieron bien las especies?"}},{"slug":"comunidad-1.s3.p11.v2","orden":11,"grupo":"comunidad-1.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto plantó 50 árboles y al año sobrevivieron 40. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"40 ÷ 50 × 100 = 80 %. Medir la supervivencia permite aprender: ¿faltó riego?, ¿se eligieron bien las especies?"}},{"slug":"comunidad-1.s3.p11.v3","orden":11,"grupo":"comunidad-1.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto plantó 20 árboles y al año sobrevivieron 17. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1.7,"explicacion":"17 ÷ 20 × 100 = 85 %. Medir la supervivencia permite aprender: ¿faltó riego?, ¿se eligieron bien las especies?"}},{"slug":"comunidad-1.s3.p12","orden":12,"grupo":"comunidad-1.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de un grupo de vecinos y marcá los problemas.","segmentos":[{"id":"s1","texto":"Contamos los árboles que faltan en cada cuadra."},{"id":"s2","texto":"Nuestro objetivo es \"salvar el planeta\"."},{"id":"s3","texto":"Pedimos permiso al municipio y plantines al vivero."},{"id":"s4","texto":"Juan va a hacer todas las tareas porque tiene tiempo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proyecto tiene un objetivo concreto y tareas compartidas.","por_opcion":{"s2":"Es demasiado general: conviene un objetivo concreto y medible.","s4":"Si todo depende de una persona, el proyecto es frágil."}}},{"slug":"comunidad-1.s3.p13","orden":13,"grupo":"comunidad-1.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Todo proyecto empieza con un {{0}}; necesita un objetivo {{1}}; y termina con una {{2}}.","banco":[{"id":"w1","texto":"diagnóstico"},{"id":"w2","texto":"concreto"},{"id":"w3","texto":"evaluación"},{"id":"w4","texto":"festejo"},{"id":"w5","texto":"general"},{"id":"w6","texto":"queja"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La estructura de cualquier proyecto comunitario."}}]},{"slug":"comunidad-1.s4","orden":4,"tipo":"leccion","titulo_es":"Hablar para sumar","bajada_es":"Escuchar, partir de lo que le importa al otro y contar historias cercanas: cómo conversar de ambiente para que la gente se acerque.","minutos":11,"pasos":[{"slug":"comunidad-1.s4.p1","orden":1,"grupo":"comunidad-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Empezar por lo que le importa al otro","cuerpo":["Las personas se interesan por el ambiente por razones distintas: la salud de sus hijos, el ahorro de plata, el amor por un lugar, la fe, la justicia, el trabajo. Una conversación funciona mejor cuando parte de lo que le importa a la otra persona, en lugar de lo que le importa a quien habla.","Por ejemplo, a alguien preocupado por la plata le puede interesar más el ahorro de la eficiencia energética que las toneladas de CO₂."]},"solucion":{}},{"slug":"comunidad-1.s4.p2","orden":2,"grupo":"comunidad-1.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada interés con una forma de hablar de ambiente que conecta con él.","izquierda":[{"id":"a1","texto":"Ahorro de plata"},{"id":"a2","texto":"Salud de los chicos"},{"id":"a3","texto":"Amor por un lugar"},{"id":"a4","texto":"Justicia"}],"derecha":[{"id":"b1","texto":"Cuánto se ahorra en la factura con eficiencia"},{"id":"b2","texto":"Aire limpio y calles seguras para ir a la escuela"},{"id":"b3","texto":"Cuidar el río o la sierra donde creciste"},{"id":"b4","texto":"Quiénes sufren más la contaminación y los extremos del clima"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El mismo tema puede contarse de muchas formas. La mejor es la que conecta con el otro."}},{"slug":"comunidad-1.s4.p3","orden":3,"grupo":"comunidad-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Escuchar primero","cuerpo":["En una conversación difícil, escuchar primero y hacer preguntas abiertas (\"¿qué te preocupa?\", \"¿cómo lo ves vos?\") genera más confianza que dar datos de entrada. Cuando alguien se siente escuchado, está más dispuesto a escuchar.","Los datos siguen siendo importantes, pero funcionan mejor dentro de una historia cercana que en una lista de números."]},"solucion":{}},{"slug":"comunidad-1.s4.p4","orden":4,"grupo":"comunidad-1.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu tía dice que \"eso del cambio climático es exagerado\". ¿Qué conviene hacer primero?","opciones":[{"id":"o1","texto":"Preguntarle qué la hace pensar eso y escucharla"},{"id":"o2","texto":"Mostrarle diez gráficos de temperatura seguidos"},{"id":"o3","texto":"Decirle que está equivocada y cambiar de tema"},{"id":"o4","texto":"Mandarle un video largo sin comentarios"}]},"solucion":{"clave":["o1"],"explicacion":"Escuchar primero no es darle la razón: es entender desde dónde habla, para poder conversar de verdad.","por_opcion":{"o3":"Cortar la conversación cierra la puerta; escuchar la abre."}}},{"slug":"comunidad-1.s4.p5","orden":5,"grupo":"comunidad-1.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para convencer a alguien, lo mejor es darle la mayor cantidad posible de datos de una sola vez.","razones":[{"id":"r1","texto":"Porque una avalancha de datos suele generar rechazo"},{"id":"r2","texto":"Porque los datos no sirven nunca"},{"id":"r3","texto":"Porque las personas no entienden los números"}]},"solucion":{"valor":false,"explicacion":"Una avalancha de datos suele generar rechazo. Conecta mejor partir de lo que le importa, escuchar y usar pocos datos bien elegidos dentro de una historia.","clave":["r1"]}},{"slug":"comunidad-1.s4.p6","orden":6,"grupo":"comunidad-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Historias cercanas y soluciones","cuerpo":["Los problemas lejanos y enormes —los polos, el planeta entero— pueden generar distancia o angustia. Las historias cercanas —el arroyo del barrio, la ola de calor del último verano, la cooperativa que recicla en tu ciudad— conectan más.","Y hablar de soluciones que ya están funcionando genera más ganas de actuar que hablar solo de catástrofes."]},"solucion":{}},{"slug":"comunidad-1.s4.p7","orden":7,"grupo":"comunidad-1.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta forma de contar suele acercar o alejar a la gente?","grupos":[{"id":"g1","nombre":"Acerca"},{"id":"g2","nombre":"Aleja"}],"items":[{"id":"i1","texto":"La historia de una cooperativa de recicladores del barrio"},{"id":"i2","texto":"Solo imágenes de catástrofes sin salida"},{"id":"i3","texto":"Cuánto ahorró una familia con burletes"},{"id":"i4","texto":"Culpar a quien escucha de todos los problemas"},{"id":"i5","texto":"Cómo volvieron los pájaros a la plaza con nativas"},{"id":"i6","texto":"Una lista de veinte datos sin contexto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cercanía y soluciones acercan. Culpa y catástrofe sin salida alejan."}},{"slug":"comunidad-1.s4.p8","orden":8,"grupo":"comunidad-1.s4.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una conversación que suma.","items":[{"id":"i1","texto":"Preguntar qué le preocupa a la otra persona"},{"id":"i2","texto":"Escuchar sin interrumpir"},{"id":"i3","texto":"Encontrar algo en común"},{"id":"i4","texto":"Contar una historia cercana con una solución"},{"id":"i5","texto":"Invitar a una acción concreta y fácil"},{"id":"i6","texto":"Empezar diciendo que está todo perdido"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Escuchar, conectar, contar y proponer: una conversación que abre puertas."}},{"slug":"comunidad-1.s4.p9","orden":9,"grupo":"comunidad-1.s4.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene evitar al hablar de ambiente con alguien que piensa distinto? Marcá todo.","opciones":[{"id":"o1","texto":"Burlarse de lo que piensa"},{"id":"o2","texto":"Culparlo de todo"},{"id":"o3","texto":"Dar una catarata de datos sin escuchar"},{"id":"o4","texto":"Hablar solo de catástrofes sin soluciones"},{"id":"o5","texto":"Hacer preguntas abiertas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las preguntas abiertas son justamente lo que conviene hacer."}},{"slug":"comunidad-1.s4.p10","orden":10,"grupo":"comunidad-1.s4.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas invitaciones de la más fácil de aceptar a la más difícil, para alguien que recién empieza.","items":[{"id":"i1","texto":"\"¿Venís el sábado un rato a la plantación de la plaza?\""},{"id":"i2","texto":"\"¿Te sumás a separar los reciclables en casa?\""},{"id":"i3","texto":"\"¿Querés organizar vos la próxima jornada?\""},{"id":"i4","texto":"\"Tenés que cambiar toda tu forma de vivir\""}],"extremos":["Más fácil","Más difícil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Empezar con algo fácil y concreto permite que las personas se sumen de a poco.","valores":{"i1":"muy fácil","i2":"fácil","i3":"difícil","i4":"muy difícil"}}},{"slug":"comunidad-1.s4.p11","orden":11,"grupo":"comunidad-1.s4.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estas es una pregunta abierta, que invita a conversar?","opciones":[{"id":"o1","texto":"¿Qué es lo que más te preocupa del barrio?"},{"id":"o2","texto":"¿No te importa el planeta, no?"},{"id":"o3","texto":"¿Estás de acuerdo conmigo, sí o no?"},{"id":"o4","texto":"¿Viste que yo tenía razón?"}]},"solucion":{"clave":["o1"],"explicacion":"Las preguntas abiertas invitan a la otra persona a contar lo que piensa.","por_opcion":{"o3":"Las preguntas de sí o no cierran la conversación; las abiertas la abren."}}},{"slug":"comunidad-1.s4.p12","orden":12,"grupo":"comunidad-1.s4.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Hablar de soluciones que ya funcionan suele generar más ganas de actuar que hablar solo de catástrofes.","razones":[{"id":"r1","texto":"Porque muestran que actuar sirve"},{"id":"r2","texto":"Porque las catástrofes no existen"},{"id":"r3","texto":"Porque a nadie le interesan las soluciones"}]},"solucion":{"valor":true,"explicacion":"Las soluciones muestran que se puede hacer algo; las catástrofes sin salida suelen generar impotencia y rechazo.","clave":["r1"]}},{"slug":"comunidad-1.s4.p13","orden":13,"grupo":"comunidad-1.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje que alguien quiere mandar al grupo de la familia y marcá lo que puede alejar.","segmentos":[{"id":"s1","texto":"Este finde plantamos árboles en la plaza, ¿alguien se suma?"},{"id":"s2","texto":"Si no venís es porque no te importa el planeta."},{"id":"s3","texto":"Llevamos mate y facturas."},{"id":"s4","texto":"Igual ya es tarde, el mundo se termina."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Invitar sin culpa y con esperanza suma mucho más.","por_opcion":{"s2":"Culpar aleja; mejor invitar sin juzgar.","s4":"El mensaje de catástrofe sin salida desanima a actuar."}}},{"slug":"comunidad-1.s4.p14","orden":14,"grupo":"comunidad-1.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para hablar de ambiente conviene {{0}} primero, partir de lo que le {{1}} al otro y contar historias con {{2}}.","banco":[{"id":"w1","texto":"escuchar"},{"id":"w2","texto":"importa"},{"id":"w3","texto":"soluciones"},{"id":"w4","texto":"gritar"},{"id":"w5","texto":"molesta"},{"id":"w6","texto":"culpas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para conversaciones que suman."}}]},{"slug":"comunidad-1.s5","orden":5,"tipo":"leccion","titulo_es":"Ecoansiedad y esperanza activa","bajada_es":"La preocupación por el ambiente es comprensible. Cómo reconocerla, cuidarse y convertirla en acción.","minutos":11,"pasos":[{"slug":"comunidad-1.s5.p1","orden":1,"grupo":"comunidad-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es la ecoansiedad","cuerpo":["La ecoansiedad es la preocupación, el miedo o la angustia que siente mucha gente frente a los problemas ambientales, sobre todo el cambio climático. No es una enfermedad: es una reacción comprensible frente a un problema real. Estudios con niños y jóvenes de distintos países encontraron que muchos sienten preocupación, tristeza o enojo por el futuro del planeta.","Se vuelve un problema cuando paraliza, afecta el sueño o la vida cotidiana, o lleva a la desesperanza."]},"solucion":{}},{"slug":"comunidad-1.s5.p2","orden":2,"grupo":"comunidad-1.s5.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Sentir preocupación por el cambio climático es un trastorno mental.","razones":[{"id":"r1","texto":"Porque es una reacción comprensible frente a un problema real"},{"id":"r2","texto":"Porque nadie se preocupa por el ambiente"},{"id":"r3","texto":"Porque preocuparse cura el problema"}]},"solucion":{"valor":false,"explicacion":"Es una reacción comprensible frente a un problema real. Solo se vuelve un problema de salud cuando paraliza o afecta mucho la vida cotidiana; en ese caso, conviene pedir ayuda.","clave":["r1"]}},{"slug":"comunidad-1.s5.p3","orden":3,"grupo":"comunidad-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué ayuda","cuerpo":["Varias cosas ayudan a transformar la angustia en algo más llevadero: hablar de lo que se siente con otras personas, informarse con fuentes confiables sin sobreexponerse a noticias catastróficas, hacer algo concreto (la acción reduce la sensación de impotencia), participar con otros y conectar con la naturaleza.","Si la angustia es muy fuerte o dura mucho, es importante hablar con alguien de confianza o con un profesional de la salud mental."]},"solucion":{}},{"slug":"comunidad-1.s5.p4","orden":4,"grupo":"comunidad-1.s5.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a manejar la ecoansiedad? Marcá todo.","opciones":[{"id":"o1","texto":"Hablar de lo que se siente"},{"id":"o2","texto":"Hacer algo concreto con otros"},{"id":"o3","texto":"Informarse con fuentes confiables sin sobreexponerse"},{"id":"o4","texto":"Pasar tiempo en la naturaleza"},{"id":"o5","texto":"Mirar noticias catastróficas todo el día"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La sobreexposición a noticias angustiantes aumenta la ansiedad. Actuar con otros y conectar con la naturaleza, en cambio, ayudan."}},{"slug":"comunidad-1.s5.p5","orden":5,"grupo":"comunidad-1.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Esperanza activa","cuerpo":["La esperanza activa no es pensar que todo va a salir bien solo: es actuar para que salga mejor, aunque no haya garantías. Se apoya en hechos reales: la capa de ozono se está recuperando, las energías renovables crecieron muchísimo, especies que estaban al borde de desaparecer se recuperaron, ríos contaminados se limpiaron.","Cada décima de grado de calentamiento que se evita importa. No es \"todo o nada\": cuanto más se haga, mejor."]},"solucion":{}},{"slug":"comunidad-1.s5.p6","orden":6,"grupo":"comunidad-1.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la acción puede reducir la angustia.","items":[{"id":"i1","texto":"Una persona siente angustia por el ambiente"},{"id":"i2","texto":"Se suma a un grupo que planta árboles en su barrio"},{"id":"i3","texto":"Conoce gente con las mismas preocupaciones"},{"id":"i4","texto":"Ve resultados concretos de lo que hacen"},{"id":"i5","texto":"Siente menos impotencia y más esperanza"},{"id":"i6","texto":"La acción hace que el problema desaparezca del todo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La acción colectiva no resuelve todo, pero cambia cómo se vive la preocupación."}},{"slug":"comunidad-1.s5.p7","orden":7,"grupo":"comunidad-1.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un hecho que alimenta la esperanza activa o un pensamiento que paraliza?","grupos":[{"id":"g1","nombre":"Alimenta la esperanza"},{"id":"g2","nombre":"Paraliza"}],"items":[{"id":"i1","texto":"La capa de ozono se está recuperando"},{"id":"i2","texto":"Ya es tarde, no hay nada que hacer"},{"id":"i3","texto":"Las renovables crecieron muchísimo en diez años"},{"id":"i4","texto":"Lo que yo haga no importa"},{"id":"i5","texto":"El yaguareté volvió a nacer en los Esteros del Iberá"},{"id":"i6","texto":"Si no se resuelve todo, no sirve nada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La esperanza activa se apoya en hechos y en que cada avance cuenta."}},{"slug":"comunidad-1.s5.p8","orden":8,"grupo":"comunidad-1.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una compañera dice que está muy angustiada por el clima y no puede dormir. ¿Qué es lo más adecuado?","opciones":[{"id":"o1","texto":"Escucharla y sugerir pedir ayuda"},{"id":"o2","texto":"Decirle que exagera y que no piense en eso"},{"id":"o3","texto":"Mostrarle más noticias sobre el tema para que se informe"},{"id":"o4","texto":"Decirle que tiene razón y que todo está perdido"}]},"solucion":{"clave":["o1"],"explicacion":"Escuchar sin minimizar y, si afecta el sueño o la vida diaria, buscar ayuda.","por_opcion":{"o3":"Si ya está angustiada, más noticias pueden empeorarlo."}}},{"slug":"comunidad-1.s5.p9","orden":9,"grupo":"comunidad-1.s5.p9","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada estrategia con cómo ayuda.","izquierda":[{"id":"a1","texto":"Hablar con otros"},{"id":"a2","texto":"Actuar en grupo"},{"id":"a3","texto":"Limitar las noticias"},{"id":"a4","texto":"Contacto con la naturaleza"}],"derecha":[{"id":"b1","texto":"Saber que no estás solo"},{"id":"b2","texto":"Reduce la sensación de impotencia"},{"id":"b3","texto":"Evita la sobreexposición"},{"id":"b4","texto":"Descansa y reconecta con lo que se quiere cuidar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Estrategias simples que ayudan a sostener el compromiso sin quemarse."}},{"slug":"comunidad-1.s5.p10","orden":10,"grupo":"comunidad-1.s5.p10","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas frases de la más útil a la menos útil para alguien con ecoansiedad.","items":[{"id":"i1","texto":"\"Es entendible lo que sentís; ¿querés que hagamos algo juntos?\""},{"id":"i2","texto":"\"Hay avances reales, como la capa de ozono\""},{"id":"i3","texto":"\"No pienses en eso\""},{"id":"i4","texto":"\"Ya es tarde, no hay nada que hacer\""}],"extremos":["Más útil","Menos útil"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Validar, acompañar y mostrar caminos: eso ayuda. Minimizar o dramatizar, no.","valores":{"i1":"escucha e invita","i2":"da esperanza con hechos","i3":"minimiza","i4":"paraliza"}}},{"slug":"comunidad-1.s5.p11","orden":11,"grupo":"comunidad-1.s5.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo en redes y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Si te angustia el clima, hablalo con alguien."},{"id":"s2","texto":"Leé todas las noticias de catástrofes que encuentres para estar informado."},{"id":"s3","texto":"Sumarte a un grupo que actúa ayuda a sentirte menos solo."},{"id":"s4","texto":"Si no se puede resolver todo, no vale la pena hacer nada."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cuidarse también es parte de cuidar el ambiente a largo plazo.","por_opcion":{"s2":"La sobreexposición a noticias catastróficas aumenta la angustia.","s4":"Cada avance importa: no es todo o nada."}}},{"slug":"comunidad-1.s5.p12","orden":12,"grupo":"comunidad-1.s5.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La preocupación por los problemas ambientales se llama {{0}}; actuar sin garantías pero con compromiso es esperanza {{1}}.","banco":[{"id":"w1","texto":"ecoansiedad"},{"id":"w2","texto":"activa"},{"id":"w3","texto":"nostalgia"},{"id":"w4","texto":"pasiva"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para sostener el compromiso sin paralizarse."}},{"slug":"comunidad-1.s5.p13","orden":13,"grupo":"comunidad-1.s5.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Frente al cambio climático, ¿qué significa decir que \"no es todo o nada\"?","opciones":[{"id":"o1","texto":"Que cada décima de grado evitada reduce daños"},{"id":"o2","texto":"Que si no se evita todo, no sirve de nada"},{"id":"o3","texto":"Que ya no se puede hacer nada útil"},{"id":"o4","texto":"Que solo importa lo que hagan los demás países"}]},"solucion":{"clave":["o1"],"explicacion":"No hay un umbral mágico después del cual todo da igual: cuanto menos calentamiento, menos impactos. Por eso ninguna acción es inútil si suma en la dirección correcta.","por_opcion":{"o3":"Es al revés: siempre hay daños que se pueden evitar."}}}]},{"slug":"comunidad-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: del yo al nosotros","bajada_es":"Bienes comunes, contagio social, proyectos, comunicación y esperanza, mezclados.","minutos":8,"pasos":[{"slug":"comunidad-1.s6.p1","orden":1,"grupo":"comunidad-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Del yo al nosotros». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"comunidad-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la plaza abandonada","bajada_es":"Un grupo de vecinos quiere recuperar la plaza de la cuadra. Armá con ellos el proyecto completo.","minutos":10,"pasos":[{"slug":"comunidad-1.s7.p1","orden":1,"grupo":"comunidad-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La plaza","cuerpo":["La plaza del barrio tiene los canteros secos, basura acumulada en una esquina, dos bancos rotos y ningún árbol nuevo desde hace años. Un grupo de cinco vecinos quiere recuperarla. En la cuadra hay una escuela, un club de barrio, una ferretería y un centro de jubilados. El municipio tiene un vivero de nativas.","Algunos vecinos dicen que \"no tiene sentido, la van a romper de nuevo\"."]},"solucion":{}},{"slug":"comunidad-1.s7.p2","orden":2,"grupo":"comunidad-1.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el mejor primer paso?","opciones":[{"id":"o1","texto":"Hacer un diagnóstico con los vecinos y la escuela"},{"id":"o2","texto":"Plantar árboles el sábado sin hablar con nadie"},{"id":"o3","texto":"Pedirle al municipio que lo haga todo"},{"id":"o4","texto":"Poner rejas alrededor de la plaza"}]},"solucion":{"clave":["o1"],"explicacion":"Entender qué pasa y qué quiere la gente hace que el proyecto sea de todos, y que lo cuiden.","por_opcion":{"o3":"El municipio es un aliado clave, pero sin diagnóstico ni participación el proyecto es frágil."}}},{"slug":"comunidad-1.s7.p3","orden":3,"grupo":"comunidad-1.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el objetivo más adecuado para empezar?","opciones":[{"id":"o1","texto":"Limpiar la esquina y plantar 10 nativas"},{"id":"o2","texto":"Que el barrio sea el más lindo de la ciudad"},{"id":"o3","texto":"Que nadie vuelva a tirar basura nunca"},{"id":"o4","texto":"Cambiar la mentalidad de todos los vecinos"}]},"solucion":{"clave":["o1"],"explicacion":"Concreto, medible y alcanzable: así se arranca y se puede mostrar un logro.","por_opcion":{"o3":"Es deseable, pero no se puede medir ni garantizar al empezar."}}},{"slug":"comunidad-1.s7.p4","orden":4,"grupo":"comunidad-1.s7.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Asigná cada aliado a lo que puede aportar.","grupos":[{"id":"g1","nombre":"Plantines y permisos"},{"id":"g2","nombre":"Personas y difusión"},{"id":"g3","nombre":"Herramientas"}],"items":[{"id":"i1","texto":"Vivero municipal"},{"id":"i2","texto":"Escuela"},{"id":"i3","texto":"Ferretería"},{"id":"i4","texto":"Municipio"},{"id":"i5","texto":"Club de barrio"},{"id":"i6","texto":"Centro de jubilados"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g2"},"explicacion":"Cada aliado aporta una pieza. El mapa de aliados convierte un grupo de cinco en un barrio."}},{"slug":"comunidad-1.s7.p5","orden":5,"grupo":"comunidad-1.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a que los vecinos cuiden la plaza después? Marcá todo.","opciones":[{"id":"o1","texto":"Que participen en decidir y en plantar"},{"id":"o2","texto":"Carteles con los nombres de quienes plantaron cada árbol"},{"id":"o3","texto":"Turnos de riego compartidos"},{"id":"o4","texto":"Contar los avances en el grupo del barrio"},{"id":"o5","texto":"Hacerlo en secreto para que sea una sorpresa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo que la gente ayudó a construir, lo cuida. La participación es la mejor protección."}},{"slug":"comunidad-1.s7.p6","orden":6,"grupo":"comunidad-1.s7.p6","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un vecino escribe el mensaje de convocatoria. Marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"Este sábado a las 10 recuperamos juntos la plaza."},{"id":"s2","texto":"Si no venís, después no te quejes de la basura."},{"id":"s3","texto":"Ya se sumaron la escuela y el club."},{"id":"s4","texto":"Total, seguro la rompen otra vez."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Invitar en positivo, mostrar que otros ya se sumaron y evitar la culpa.","por_opcion":{"s2":"Culpar aleja: mejor invitar en positivo.","s4":"El mensaje derrotista desanima antes de empezar."}}},{"slug":"comunidad-1.s7.p7","orden":7,"grupo":"comunidad-1.s7.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Plantaron 10 nativas y a los seis meses sobreviven 8. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"8 ÷ 10 × 100 = 80 %. Contarlo en el grupo del barrio muestra resultados y suma gente para la próxima etapa."}},{"slug":"comunidad-1.s7.p7.v2","orden":7,"grupo":"comunidad-1.s7.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Plantaron 20 nativas y a los seis meses sobreviven 17. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1.7,"explicacion":"17 ÷ 20 × 100 = 85 %. Contarlo en el grupo del barrio muestra resultados y suma gente para la próxima etapa."}},{"slug":"comunidad-1.s7.p7.v3","orden":7,"grupo":"comunidad-1.s7.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Plantaron 15 nativas y a los seis meses sobreviven 12. ¿Qué porcentaje sobrevivió?","unidad":"%","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"12 ÷ 15 × 100 = 80 %. Contarlo en el grupo del barrio muestra resultados y suma gente para la próxima etapa."}},{"slug":"comunidad-1.s7.p8","orden":8,"grupo":"comunidad-1.s7.p8","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el proyecto completo.","items":[{"id":"i1","texto":"Reunión con vecinos y escuela para el diagnóstico"},{"id":"i2","texto":"Acordar el objetivo: limpiar la esquina y plantar 10 nativas"},{"id":"i3","texto":"Conseguir plantines, permisos y herramientas"},{"id":"i4","texto":"Jornada de limpieza y plantación"},{"id":"i5","texto":"Turnos de riego y medición de la supervivencia"},{"id":"i6","texto":"Contar los resultados y planear la segunda etapa"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Del diagnóstico a la segunda etapa: un proyecto que puede crecer."}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"comunidad-2","rama":"comunidad","orden":2,"nivel":1,"titulo_es":"Derechos y participación ambiental","bajada_es":"Tenés derecho a un ambiente sano, a saber qué pasa con él y a participar en las decisiones. Qué dicen la Constitución y las leyes, y cómo usarlas.","objetivos_es":["Explicar el derecho a un ambiente sano del artículo 41 de la Constitución Nacional","Reconocer los principios de la Ley General del Ambiente","Ejercer el derecho de acceso a la información pública ambiental","Identificar las formas de participación ciudadana en decisiones ambientales","Relacionar la educación ambiental y los ODS con la acción local"],"repasa":["comunidad-1","tronco-3"],"requiere_tronco":1,"fuentes":["ley-25675-ambiente","ley-25831-info","escazu","ley-27621-eai","onu-ods","unesco-ods","acumar"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"comunidad-2.s1","orden":1,"tipo":"leccion","titulo_es":"El derecho a un ambiente sano","bajada_es":"Qué dice el artículo 41 de la Constitución, qué significa y qué deberes trae.","minutos":11,"pasos":[{"slug":"comunidad-2.s1.p1","orden":1,"grupo":"comunidad-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El artículo 41","cuerpo":["Desde la reforma de 1994, la Constitución Nacional reconoce en su artículo 41 que todos los habitantes gozan del derecho a un ambiente sano, equilibrado, apto para el desarrollo humano y para que las actividades productivas satisfagan las necesidades presentes sin comprometer las de las generaciones futuras. Y agrega que tienen el deber de preservarlo.","También establece que el daño ambiental genera, prioritariamente, la obligación de recomponer: es decir, de reparar el ambiente dañado, no solo de pagar."],"destacado":{"valor":"Art. 41","texto":"de la Constitución Nacional reconoce el derecho a un ambiente sano y el deber de preservarlo."}},"solucion":{}},{"slug":"comunidad-2.s1.p2","orden":2,"grupo":"comunidad-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué establece el artículo 41 de la Constitución? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"El derecho de todos a un ambiente sano"},{"id":"o2","texto":"El deber de preservarlo"},{"id":"o3","texto":"Que no se comprometa a las generaciones futuras"},{"id":"o4","texto":"Que el daño ambiental obliga prioritariamente a recomponer"},{"id":"o5","texto":"Que solo los dueños de tierras tienen derechos ambientales"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un derecho de todos, con deberes, que piensa en el futuro y prioriza reparar."}},{"slug":"comunidad-2.s1.p3","orden":3,"grupo":"comunidad-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Derechos y deberes","cuerpo":["El derecho a un ambiente sano no es solo algo que se reclama: viene con el deber de cuidarlo. Además, la Constitución obliga a las autoridades a proteger ese derecho, a usar racionalmente los recursos, a preservar el patrimonio natural y cultural y la diversidad biológica, y a informar y educar.","La Nación dicta los \"presupuestos mínimos\" de protección ambiental, que valen en todo el país, y las provincias pueden complementarlos con normas más exigentes."]},"solucion":{}},{"slug":"comunidad-2.s1.p4","orden":4,"grupo":"comunidad-2.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un derecho o un deber que surge del artículo 41?","grupos":[{"id":"g1","nombre":"Derecho"},{"id":"g2","nombre":"Deber"}],"items":[{"id":"i1","texto":"Vivir en un ambiente sano"},{"id":"i2","texto":"Preservar el ambiente"},{"id":"i3","texto":"Recibir información ambiental"},{"id":"i4","texto":"No comprometer a las generaciones futuras"},{"id":"i5","texto":"Que se recomponga un daño ambiental"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Derechos y deberes van juntos. Nadie tiene derecho a dañar el ambiente de todos."}},{"slug":"comunidad-2.s1.p5","orden":5,"grupo":"comunidad-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El derecho a un ambiente sano solo protege a las personas que viven hoy.","razones":[{"id":"r1","texto":"Porque menciona explícitamente a las generaciones futuras"},{"id":"r2","texto":"Porque la Constitución no habla del ambiente"},{"id":"r3","texto":"Porque solo protege a los adultos"}]},"solucion":{"valor":false,"explicacion":"El artículo 41 habla explícitamente de no comprometer las necesidades de las generaciones futuras.","clave":["r1"]}},{"slug":"comunidad-2.s1.p6","orden":6,"grupo":"comunidad-2.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una fábrica contamina un arroyo. Según el artículo 41, ¿qué corresponde en primer lugar?","opciones":[{"id":"o1","texto":"Recomponer el ambiente dañado"},{"id":"o2","texto":"Pagar una multa y seguir igual"},{"id":"o3","texto":"Mudar a los vecinos a otro barrio"},{"id":"o4","texto":"Nada, porque la fábrica da trabajo"}]},"solucion":{"clave":["o1"],"explicacion":"Recomponer es la prioridad: devolver el ambiente a su estado anterior en lo posible.","por_opcion":{"o3":"La obligación prioritaria es reparar el daño, no trasladar el problema."}}},{"slug":"comunidad-2.s1.p7","orden":7,"grupo":"comunidad-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Presupuestos mínimos","cuerpo":["Las leyes de presupuestos mínimos fijan una protección básica común para todo el país: por ejemplo, la Ley General del Ambiente, la de bosques nativos, la de glaciares, la de residuos domiciliarios. Las provincias y los municipios no pueden proteger menos, pero sí pueden proteger más."]},"solucion":{}},{"slug":"comunidad-2.s1.p8","orden":8,"grupo":"comunidad-2.s1.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ley de presupuestos mínimos con su tema.","izquierda":[{"id":"a1","texto":"Ley 25.675"},{"id":"a2","texto":"Ley 26.331"},{"id":"a3","texto":"Ley 26.639"},{"id":"a4","texto":"Ley 25.916"}],"derecha":[{"id":"b1","texto":"Ley General del Ambiente"},{"id":"b2","texto":"Bosques nativos"},{"id":"b3","texto":"Glaciares y ambiente periglacial"},{"id":"b4","texto":"Residuos domiciliarios"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Leyes que ya viste en otras ramas, unidas por la misma lógica: un piso común para todo el país."}},{"slug":"comunidad-2.s1.p9","orden":9,"grupo":"comunidad-2.s1.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo funcionan los presupuestos mínimos.","items":[{"id":"i1","texto":"La Nación dicta una ley de presupuestos mínimos"},{"id":"i2","texto":"Fija una protección básica para todo el país"},{"id":"i3","texto":"Una provincia puede dictar normas más exigentes"},{"id":"i4","texto":"Nunca puede proteger menos que el piso nacional"},{"id":"i5","texto":"Cada provincia puede ignorar la ley nacional"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un piso común y la posibilidad de subir la vara según cada lugar."}},{"slug":"comunidad-2.s1.p10","orden":10,"grupo":"comunidad-2.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Constitución reconoce el derecho a un ambiente sano desde 1994."},{"id":"s2","texto":"Ese derecho no trae ningún deber para los habitantes."},{"id":"s3","texto":"El daño ambiental obliga prioritariamente a recomponer."},{"id":"s4","texto":"Una provincia puede proteger menos que la ley nacional de presupuestos mínimos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer bien el marco legal es la base para ejercer los derechos.","por_opcion":{"s2":"El artículo 41 establece también el deber de preservar el ambiente.","s4":"Puede proteger más, pero nunca menos que el piso nacional."}}},{"slug":"comunidad-2.s1.p11","orden":11,"grupo":"comunidad-2.s1.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El artículo {{0}} de la Constitución reconoce el derecho a un ambiente sano; el daño ambiental obliga prioritariamente a {{1}}.","banco":[{"id":"w1","texto":"41"},{"id":"w2","texto":"recomponer"},{"id":"w3","texto":"14"},{"id":"w4","texto":"indemnizar"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Las dos ideas centrales del artículo 41, en una línea."}},{"slug":"comunidad-2.s1.p12","orden":12,"grupo":"comunidad-2.s1.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año se incorporó el derecho a un ambiente sano a la Constitución Nacional.","min":1853,"max":2024,"paso":1,"unidad":"año","escala":"lineal"},"solucion":{"valor":1994,"banda":"lineal","explicacion":"En la reforma de 1994, con el artículo 41. Desde entonces es un derecho de rango constitucional."}},{"slug":"comunidad-2.s1.p13","orden":13,"grupo":"comunidad-2.s1.p13","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas normas de mayor a menor jerarquía.","items":[{"id":"i1","texto":"Constitución Nacional (art. 41)"},{"id":"i2","texto":"Ley nacional de presupuestos mínimos"},{"id":"i3","texto":"Ley provincial ambiental"},{"id":"i4","texto":"Ordenanza municipal"}],"extremos":["Mayor jerarquía","Menor jerarquía"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada nivel respeta al de arriba y puede sumar protección para su territorio.","valores":{"i1":"la de mayor jerarquía","i2":"aplica en todo el país","i3":"complementa en la provincia","i4":"aplica en el municipio"}}}]},{"slug":"comunidad-2.s2","orden":2,"tipo":"leccion","titulo_es":"La Ley General del Ambiente","bajada_es":"Los principios de la Ley 25.675, la evaluación de impacto ambiental y la participación ciudadana.","minutos":11,"pasos":[{"slug":"comunidad-2.s2.p1","orden":1,"grupo":"comunidad-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una ley marco","cuerpo":["La Ley 25.675, General del Ambiente, sancionada en 2002, es la ley marco de la política ambiental argentina. Establece objetivos, principios, instrumentos de gestión (como la evaluación de impacto ambiental), la participación ciudadana, el acceso a la información y reglas sobre el daño ambiental."]},"solucion":{}},{"slug":"comunidad-2.s2.p2","orden":2,"grupo":"comunidad-2.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los principios","cuerpo":["La ley fija principios que guían la interpretación de las normas ambientales. Entre ellos: el principio preventivo (atender las causas de los problemas antes de que ocurran); el precautorio (cuando hay peligro de daño grave o irreversible, la falta de certeza científica no puede usarse como excusa para no actuar); la equidad intergeneracional (cuidar el ambiente para las generaciones futuras); la progresividad (metas graduales); la responsabilidad (quien daña, se hace cargo); y la solidaridad y la cooperación entre jurisdicciones."],"lista":["Preventivo","Precautorio","Equidad intergeneracional","Progresividad","Responsabilidad","Solidaridad y cooperación"]},"solucion":{}},{"slug":"comunidad-2.s2.p3","orden":3,"grupo":"comunidad-2.s2.p3","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada principio con su significado.","izquierda":[{"id":"a1","texto":"Preventivo"},{"id":"a2","texto":"Precautorio"},{"id":"a3","texto":"Equidad intergeneracional"},{"id":"a4","texto":"Responsabilidad"}],"derecha":[{"id":"b1","texto":"Atender las causas antes de que ocurra el daño"},{"id":"b2","texto":"La falta de certeza no justifica no actuar ante un daño grave"},{"id":"b3","texto":"Cuidar el ambiente para las próximas generaciones"},{"id":"b4","texto":"Quien causa un daño se hace cargo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro principios que se usan en fallos judiciales y decisiones de gobierno."}},{"slug":"comunidad-2.s2.p4","orden":4,"grupo":"comunidad-2.s2.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Hay indicios de que un químico podría causar un daño grave e irreversible, pero la ciencia todavía no tiene certeza. Según el principio precautorio, ¿qué corresponde?","opciones":[{"id":"o1","texto":"Tomar medidas de protección aunque falte certeza"},{"id":"o2","texto":"Esperar a tener certeza total antes de hacer nada"},{"id":"o3","texto":"Usarlo más para ver qué pasa"},{"id":"o4","texto":"Dejar que cada persona decida si lo usa"}]},"solucion":{"clave":["o1"],"explicacion":"La falta de certeza no puede ser excusa para no proteger ante un posible daño grave o irreversible.","por_opcion":{"o3":"Probar \"en el terreno\" un posible daño irreversible es justo lo que el principio busca evitar."}}},{"slug":"comunidad-2.s2.p5","orden":5,"grupo":"comunidad-2.s2.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Según el principio precautorio, si no hay certeza científica absoluta de un daño, no se puede hacer nada.","razones":[{"id":"r1","texto":"Porque el principio dice que la falta de certeza no justifica no actuar"},{"id":"r2","texto":"Porque la ley prohíbe actuar sin certeza"},{"id":"r3","texto":"Porque la ciencia siempre tiene certeza absoluta"}]},"solucion":{"valor":false,"explicacion":"Es al revés: cuando hay peligro de daño grave o irreversible, la falta de certeza no puede usarse como razón para no tomar medidas.","clave":["r1"]}},{"slug":"comunidad-2.s2.p6","orden":6,"grupo":"comunidad-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Evaluación de impacto ambiental","cuerpo":["La ley establece que toda obra o actividad que pueda degradar el ambiente o afectar la calidad de vida de la población de forma significativa debe pasar por un procedimiento de evaluación de impacto ambiental (EIA) antes de hacerse. En ese proceso se analizan los impactos, se proponen medidas para evitarlos o reducirlos y la autoridad decide si la aprueba.","La ley también prevé instancias de consulta o audiencias públicas, sobre todo en proyectos con impactos importantes."]},"solucion":{}},{"slug":"comunidad-2.s2.p7","orden":7,"grupo":"comunidad-2.s2.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas típicas de una evaluación de impacto ambiental.","items":[{"id":"i1","texto":"La empresa presenta el proyecto"},{"id":"i2","texto":"Se elabora un estudio de impacto ambiental"},{"id":"i3","texto":"Se abre una instancia de participación ciudadana"},{"id":"i4","texto":"La autoridad evalúa y decide"},{"id":"i5","texto":"Si se aprueba, se controla que se cumplan las condiciones"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Evaluar antes de construir, con participación y con control después."}},{"slug":"comunidad-2.s2.p8","orden":8,"grupo":"comunidad-2.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta obra probablemente necesita evaluación de impacto ambiental o no?","grupos":[{"id":"g1","nombre":"Probablemente sí"},{"id":"g2","nombre":"Probablemente no"}],"items":[{"id":"i1","texto":"Un relleno sanitario nuevo"},{"id":"i2","texto":"Pintar la fachada de una casa"},{"id":"i3","texto":"Una fábrica junto a un río"},{"id":"i4","texto":"Plantar un árbol en la vereda"},{"id":"i5","texto":"Un barrio sobre un humedal"},{"id":"i6","texto":"Cambiar las lámparas de una escuela"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La evaluación se exige a lo que puede degradar el ambiente de forma significativa."}},{"slug":"comunidad-2.s2.p9","orden":9,"grupo":"comunidad-2.s2.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué evaluar antes de construir es preventivo.","items":[{"id":"i1","texto":"Se evalúa el impacto antes de construir"},{"id":"i2","texto":"Se detectan riesgos para un humedal"},{"id":"i3","texto":"Se cambia el diseño o la ubicación del proyecto"},{"id":"i4","texto":"Se evita un daño que después costaría mucho reparar"},{"id":"i5","texto":"Evaluar después de construir es igual de efectivo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Prevenir es más barato y efectivo que reparar: el principio preventivo en acción."}},{"slug":"comunidad-2.s2.p10","orden":10,"grupo":"comunidad-2.s2.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué incluye la Ley General del Ambiente? Marcá todo.","opciones":[{"id":"o1","texto":"Principios de política ambiental"},{"id":"o2","texto":"La evaluación de impacto ambiental"},{"id":"o3","texto":"La participación ciudadana"},{"id":"o4","texto":"El acceso a la información ambiental"},{"id":"o5","texto":"La prohibición de toda actividad productiva"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Es una ley marco para compatibilizar el desarrollo con el cuidado del ambiente, no para prohibir producir."}},{"slug":"comunidad-2.s2.p11","orden":11,"grupo":"comunidad-2.s2.p11","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué principio de la Ley General del Ambiente aplica cada decisión?","grupos":[{"id":"g1","nombre":"Preventivo"},{"id":"g2","nombre":"Precautorio"},{"id":"g3","nombre":"Responsabilidad"}],"items":[{"id":"i1","texto":"Exigir filtros antes de habilitar una fábrica"},{"id":"i2","texto":"Suspender un químico con indicios de daño grave aunque falten estudios"},{"id":"i3","texto":"Obligar a quien contaminó a limpiar el arroyo"},{"id":"i4","texto":"Evaluar el impacto antes de construir"},{"id":"i5","texto":"Frenar un desmonte ante un posible daño irreversible sin certeza total"},{"id":"i6","texto":"Que la empresa pague la recomposición del suelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres principios distintos que muchas veces se aplican juntos."}},{"slug":"comunidad-2.s2.p12","orden":12,"grupo":"comunidad-2.s2.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá en qué año se sancionó la Ley General del Ambiente (25.675).","min":1950,"max":2024,"paso":1,"unidad":"año","escala":"lineal"},"solucion":{"valor":2002,"banda":"lineal","explicacion":"En 2002. Ocho años después de que la reforma constitucional incorporara el artículo 41."}},{"slug":"comunidad-2.s2.p13","orden":13,"grupo":"comunidad-2.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Ley 25.675 es la Ley General del Ambiente."},{"id":"s2","texto":"La evaluación de impacto ambiental se hace después de construir la obra."},{"id":"s3","texto":"La ley incluye el principio de equidad intergeneracional."},{"id":"s4","texto":"El principio precautorio exige certeza absoluta antes de proteger."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los principios de la ley se aplican en decisiones y fallos concretos.","por_opcion":{"s2":"Se hace antes, para prevenir daños.","s4":"Dice lo contrario: la falta de certeza no justifica no actuar ante un daño grave."}}},{"slug":"comunidad-2.s2.p14","orden":14,"grupo":"comunidad-2.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley {{0}} es la Ley General del Ambiente; su principio {{1}} dice que la falta de certeza no justifica no actuar ante un daño grave.","banco":[{"id":"w1","texto":"25.675"},{"id":"w2","texto":"precautorio"},{"id":"w3","texto":"26.331"},{"id":"w4","texto":"progresivo"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La ley marco y uno de sus principios más importantes."}}]},{"slug":"comunidad-2.s3","orden":3,"tipo":"leccion","titulo_es":"Tu derecho a saber","bajada_es":"Cómo pedir información pública ambiental con la Ley 25.831, y qué agrega el Acuerdo de Escazú.","minutos":11,"pasos":[{"slug":"comunidad-2.s3.p1","orden":1,"grupo":"comunidad-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Ley 25.831","cuerpo":["La Ley 25.831, de Régimen de Libre Acceso a la Información Pública Ambiental, garantiza que cualquier persona puede pedir información ambiental que tengan los organismos públicos y las empresas de servicios públicos. No hace falta explicar para qué se pide ni demostrar un interés especial, y el acceso es gratuito, salvo los costos de copia.","La autoridad tiene un plazo máximo de 30 días hábiles para responder. Solo puede negarse en casos específicos, por ejemplo, si la información afecta la defensa nacional o secretos comerciales protegidos, y debe fundamentar la negativa."],"destacado":{"valor":"30 días hábiles","texto":"es el plazo máximo para responder un pedido de información pública ambiental, según la Ley 25.831."}},"solucion":{}},{"slug":"comunidad-2.s3.p2","orden":2,"grupo":"comunidad-2.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué garantiza la Ley 25.831? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Que cualquier persona puede pedir información ambiental"},{"id":"o2","texto":"Que no hace falta explicar para qué se pide"},{"id":"o3","texto":"Que es gratuita, salvo costos de copia"},{"id":"o4","texto":"Un plazo máximo de 30 días hábiles para responder"},{"id":"o5","texto":"Que solo pueden pedirla los abogados"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un derecho amplio y simple: cualquiera puede pedir, sin justificar, y con un plazo definido."}},{"slug":"comunidad-2.s3.p3","orden":3,"grupo":"comunidad-2.s3.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para pedir información ambiental hay que demostrar que uno está afectado por el problema.","razones":[{"id":"r1","texto":"Porque la ley no exige acreditar interés"},{"id":"r2","texto":"Porque solo pueden pedir los afectados directos"},{"id":"r3","texto":"Porque la información ambiental es secreta"}]},"solucion":{"valor":false,"explicacion":"La ley establece que no hace falta acreditar ningún interés especial: cualquier persona puede pedir información ambiental.","clave":["r1"]}},{"slug":"comunidad-2.s3.p4","orden":4,"grupo":"comunidad-2.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo hacer un buen pedido","cuerpo":["Un buen pedido de información es claro y concreto: dice qué información se busca, de qué lugar y período, y en qué formato se prefiere recibir. Por ejemplo: \"Solicito los resultados de los análisis de calidad del agua del arroyo X realizados en los últimos dos años, en formato digital\".","Conviene guardar una copia con la fecha de presentación, para poder reclamar si no hay respuesta en el plazo."]},"solucion":{}},{"slug":"comunidad-2.s3.p5","orden":5,"grupo":"comunidad-2.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el pedido de información mejor formulado?","opciones":[{"id":"o1","texto":"Análisis del agua del arroyo X de 2023 y 2024, en digital"},{"id":"o2","texto":"Quiero saber todo lo que pasa con el ambiente del municipio"},{"id":"o3","texto":"¿Por qué el arroyo del barrio está tan sucio y quién tiene la culpa?"},{"id":"o4","texto":"Necesito que me digan si hay contaminación en algún lugar de la ciudad"}]},"solucion":{"clave":["o1"],"explicacion":"Qué, dónde, cuándo y en qué formato: así es más fácil responder y más difícil evadir.","por_opcion":{"o3":"Es una pregunta legítima, pero un pedido de información funciona mejor pidiendo documentos o datos concretos."}}},{"slug":"comunidad-2.s3.p6","orden":6,"grupo":"comunidad-2.s3.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para pedir información ambiental.","items":[{"id":"i1","texto":"Identificar qué información necesitás y quién la tiene"},{"id":"i2","texto":"Redactar un pedido claro y concreto"},{"id":"i3","texto":"Presentarlo y guardar copia con fecha"},{"id":"i4","texto":"Esperar la respuesta dentro de los 30 días hábiles"},{"id":"i5","texto":"Si no responden, reclamar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un procedimiento simple que cualquier persona o escuela puede usar."}},{"slug":"comunidad-2.s3.p7","orden":7,"grupo":"comunidad-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Acuerdo de Escazú","cuerpo":["El Acuerdo de Escazú es un tratado de América Latina y el Caribe sobre el acceso a la información, la participación pública y el acceso a la justicia en asuntos ambientales. Argentina lo aprobó por la Ley 27.566 en 2020, y entró en vigor en 2021.","Es el primer tratado del mundo que incluye disposiciones específicas para proteger a las personas defensoras de derechos humanos en asuntos ambientales, que en la región sufren amenazas y ataques."]},"solucion":{}},{"slug":"comunidad-2.s3.p8","orden":8,"grupo":"comunidad-2.s3.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada norma con lo que establece.","izquierda":[{"id":"a1","texto":"Ley 25.831"},{"id":"a2","texto":"Acuerdo de Escazú (Ley 27.566)"},{"id":"a3","texto":"Ley 25.675"},{"id":"a4","texto":"Artículo 41 de la Constitución"}],"derecha":[{"id":"b1","texto":"Acceso a la información pública ambiental"},{"id":"b2","texto":"Información, participación, justicia y protección de defensores"},{"id":"b3","texto":"Principios e instrumentos de la política ambiental"},{"id":"b4","texto":"Derecho a un ambiente sano"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un sistema de normas que se complementan."}},{"slug":"comunidad-2.s3.p9","orden":9,"grupo":"comunidad-2.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué derecho de acceso ejerce cada persona?","grupos":[{"id":"g1","nombre":"Acceso a la información"},{"id":"g2","nombre":"Participación"},{"id":"g3","nombre":"Acceso a la justicia"}],"items":[{"id":"i1","texto":"Pedir los análisis de agua de un arroyo"},{"id":"i2","texto":"Hablar en una audiencia pública"},{"id":"i3","texto":"Presentar un amparo ambiental"},{"id":"i4","texto":"Consultar el estudio de impacto de una obra"},{"id":"i5","texto":"Enviar observaciones a una consulta"},{"id":"i6","texto":"Denunciar un daño ambiental ante un juez"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Los tres pilares del Acuerdo de Escazú: saber, participar y reclamar."}},{"slug":"comunidad-2.s3.p10","orden":10,"grupo":"comunidad-2.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Presentaste un pedido el lunes 3 de marzo. Si no hay feriados, ¿cuántas semanas laborales de 5 días son los 30 días hábiles de plazo?","unidad":"semanas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, unos 42 días corridos si no hay feriados. Anotar la fecha límite ayuda a reclamar a tiempo."}},{"slug":"comunidad-2.s3.p10.v2","orden":10,"grupo":"comunidad-2.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Presentaste un pedido el martes 1 de abril. Si no hay feriados, ¿cuántas semanas laborales de 5 días son los 30 días hábiles de plazo?","unidad":"semanas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, unos 42 días corridos si no hay feriados. Anotar la fecha límite ayuda a reclamar a tiempo."}},{"slug":"comunidad-2.s3.p10.v3","orden":10,"grupo":"comunidad-2.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Presentaste un pedido el jueves 5 de junio. Si no hay feriados, ¿cuántas semanas laborales de 5 días son los 30 días hábiles de plazo?","unidad":"semanas","decimales":0},"solucion":{"valor":6,"tolerancia":0.5,"explicacion":"30 ÷ 5 = 6 semanas laborales, unos 42 días corridos si no hay feriados. Anotar la fecha límite ayuda a reclamar a tiempo."}},{"slug":"comunidad-2.s3.p11","orden":11,"grupo":"comunidad-2.s3.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El acceso a la información pública ambiental es gratuito, salvo los costos de copia.","razones":[{"id":"r1","texto":"Porque la ley lo establece así"},{"id":"r2","texto":"Porque hay que pagar una tasa por cada pregunta"},{"id":"r3","texto":"Porque solo es gratis para empresas"}]},"solucion":{"valor":true,"explicacion":"Así lo establece la Ley 25.831: el derecho no puede depender de pagar, más allá de los costos de reproducción.","clave":["r1"]}},{"slug":"comunidad-2.s3.p12","orden":12,"grupo":"comunidad-2.s3.p12","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta negativa a dar información es legítima o no?","grupos":[{"id":"g1","nombre":"Puede ser legítima (si se fundamenta)"},{"id":"g2","nombre":"No es legítima"}],"items":[{"id":"i1","texto":"La información afecta la defensa nacional"},{"id":"i2","texto":"El funcionario no tiene ganas de buscarla"},{"id":"i3","texto":"Es un secreto comercial protegido por la ley"},{"id":"i4","texto":"La persona no explicó para qué la quiere"},{"id":"i5","texto":"Los datos muestran que hay contaminación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Las excepciones son pocas y deben fundamentarse. Que los datos sean incómodos no es una razón válida."}},{"slug":"comunidad-2.s3.p13","orden":13,"grupo":"comunidad-2.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Cualquier persona puede pedir información ambiental."},{"id":"s2","texto":"Si pedís información, tenés que explicar por qué la querés."},{"id":"s3","texto":"El plazo máximo de respuesta es de 30 días hábiles."},{"id":"s4","texto":"El Acuerdo de Escazú no tiene nada que ver con Argentina."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer tus derechos de acceso es el primer paso para usarlos.","por_opcion":{"s2":"La Ley 25.831 no exige justificar el pedido.","s4":"Argentina lo aprobó por la Ley 27.566 en 2020."}}},{"slug":"comunidad-2.s3.p14","orden":14,"grupo":"comunidad-2.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley {{0}} garantiza el acceso a la información ambiental, con un plazo de {{1}} días hábiles; el Acuerdo de {{2}} protege además a las personas defensoras del ambiente.","banco":[{"id":"w1","texto":"25.831"},{"id":"w2","texto":"30"},{"id":"w3","texto":"Escazú"},{"id":"w4","texto":"25.916"},{"id":"w5","texto":"90"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las normas que sostienen el derecho a saber y a defender el ambiente."}}]},{"slug":"comunidad-2.s4","orden":4,"tipo":"leccion","titulo_es":"Participar en las decisiones","bajada_es":"Audiencias públicas, concejos deliberantes, presupuestos participativos y amparos: las herramientas para intervenir.","minutos":11,"pasos":[{"slug":"comunidad-2.s4.p1","orden":1,"grupo":"comunidad-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchas puertas","cuerpo":["Hay muchas formas de participar en decisiones ambientales: las audiencias públicas y consultas sobre proyectos con impacto; las bancas o sesiones abiertas de los concejos deliberantes; los presupuestos participativos, donde los vecinos proponen y votan proyectos; los consejos consultivos; y, cuando un derecho ambiental se vulnera, la vía judicial."]},"solucion":{}},{"slug":"comunidad-2.s4.p2","orden":2,"grupo":"comunidad-2.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que permite.","izquierda":[{"id":"a1","texto":"Audiencia pública"},{"id":"a2","texto":"Presupuesto participativo"},{"id":"a3","texto":"Concejo deliberante"},{"id":"a4","texto":"Amparo ambiental"}],"derecha":[{"id":"b1","texto":"Opinar sobre un proyecto antes de que se decida"},{"id":"b2","texto":"Proponer y votar obras para el barrio"},{"id":"b3","texto":"Presentar proyectos de ordenanza o hablar en sesiones abiertas"},{"id":"b4","texto":"Pedir a un juez que frene un daño ambiental"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro puertas distintas. Elegir la adecuada depende del problema y del momento."}},{"slug":"comunidad-2.s4.p3","orden":3,"grupo":"comunidad-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La audiencia pública","cuerpo":["En una audiencia pública, cualquier persona interesada puede inscribirse y expresar su opinión sobre un proyecto antes de que la autoridad decida. Las opiniones no son vinculantes —la autoridad no está obligada a hacer lo que se dice—, pero sí debe considerarlas y explicar cómo las tuvo en cuenta.","Participar bien implica leer el proyecto, preparar argumentos con datos y proponer alternativas."]},"solucion":{}},{"slug":"comunidad-2.s4.p4","orden":4,"grupo":"comunidad-2.s4.p4","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En una audiencia pública, la autoridad está obligada a hacer lo que diga la mayoría de los participantes.","razones":[{"id":"r1","texto":"Porque las opiniones no son vinculantes, aunque deben considerarse"},{"id":"r2","texto":"Porque en las audiencias no se puede hablar"},{"id":"r3","texto":"Porque las audiencias se hacen después de decidir"}]},"solucion":{"valor":false,"explicacion":"Las opiniones no son vinculantes, pero la autoridad debe considerarlas y fundamentar su decisión. Por eso importa participar con buenos argumentos.","clave":["r1"]}},{"slug":"comunidad-2.s4.p5","orden":5,"grupo":"comunidad-2.s4.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo prepararse para hablar en una audiencia pública.","items":[{"id":"i1","texto":"Inscribirse en el plazo indicado"},{"id":"i2","texto":"Leer el proyecto y el estudio de impacto"},{"id":"i3","texto":"Buscar datos y preparar argumentos"},{"id":"i4","texto":"Proponer alternativas concretas"},{"id":"i5","texto":"Exponer con claridad en el tiempo asignado"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una buena participación se prepara: datos, argumentos y propuestas."}},{"slug":"comunidad-2.s4.p6","orden":6,"grupo":"comunidad-2.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El amparo ambiental","cuerpo":["El artículo 43 de la Constitución permite presentar una acción de amparo, un proceso judicial rápido, contra actos u omisiones que lesionen derechos como el de un ambiente sano. En los casos ambientales, puede presentarla la persona afectada, el Defensor del Pueblo y las asociaciones que protegen el ambiente.","Uno de los casos más conocidos es la causa Mendoza, por la contaminación del Riachuelo, en la que la Corte Suprema ordenó en 2008 recomponer la cuenca, como viste en la rama de Agua."]},"solucion":{}},{"slug":"comunidad-2.s4.p7","orden":7,"grupo":"comunidad-2.s4.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa empieza a rellenar un humedal sin evaluación de impacto ambiental. ¿Qué herramienta permite pedir a un juez que lo frene rápido?","opciones":[{"id":"o1","texto":"Una acción de amparo ambiental"},{"id":"o2","texto":"Un presupuesto participativo"},{"id":"o3","texto":"Una encuesta en redes sociales"},{"id":"o4","texto":"Esperar a las próximas elecciones"}]},"solucion":{"clave":["o1"],"explicacion":"El amparo es la vía judicial rápida para proteger un derecho que se está vulnerando.","por_opcion":{"o3":"Puede servir para difundir, pero no tiene efecto legal para frenar la obra."}}},{"slug":"comunidad-2.s4.p8","orden":8,"grupo":"comunidad-2.s4.p8","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué herramienta conviene para cada situación?","grupos":[{"id":"g1","nombre":"Presupuesto participativo"},{"id":"g2","nombre":"Audiencia pública"},{"id":"g3","nombre":"Amparo ambiental"}],"items":[{"id":"i1","texto":"Proponer una huerta comunitaria en la plaza"},{"id":"i2","texto":"Opinar sobre un relleno sanitario proyectado"},{"id":"i3","texto":"Frenar un relleno ilegal de un humedal"},{"id":"i4","texto":"Pedir bicicleteros en el centro del barrio"},{"id":"i5","texto":"Dar argumentos sobre una obra en la costa del río"},{"id":"i6","texto":"Exigir que se deje de volcar un efluente tóxico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada situación pide su herramienta: proponer, opinar o reclamar ante la justicia."}},{"slug":"comunidad-2.s4.p9","orden":9,"grupo":"comunidad-2.s4.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una propuesta vecinal puede volverse ordenanza.","items":[{"id":"i1","texto":"Los vecinos detectan un problema y arman una propuesta"},{"id":"i2","texto":"Juntan firmas y apoyos"},{"id":"i3","texto":"Presentan la propuesta en el concejo deliberante"},{"id":"i4","texto":"Un concejal la toma y la presenta como proyecto"},{"id":"i5","texto":"Se debate y se vota"},{"id":"i6","texto":"La propuesta se aprueba sola al presentarla"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las ordenanzas también nacen en los barrios, cuando la propuesta está bien armada y tiene apoyo."}},{"slug":"comunidad-2.s4.p10","orden":10,"grupo":"comunidad-2.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más efectiva la participación ciudadana? Marcá todo.","opciones":[{"id":"o1","texto":"Informarse antes de opinar"},{"id":"o2","texto":"Presentar datos y argumentos"},{"id":"o3","texto":"Proponer alternativas concretas"},{"id":"o4","texto":"Sumar a otras organizaciones"},{"id":"o5","texto":"Insultar a los funcionarios"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Argumentos, propuestas y alianzas: la participación que cambia decisiones."}},{"slug":"comunidad-2.s4.p11","orden":11,"grupo":"comunidad-2.s4.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Quiénes pueden presentar un amparo ambiental según el artículo 43 de la Constitución? Marcá todos.","opciones":[{"id":"o1","texto":"La persona afectada"},{"id":"o2","texto":"El Defensor del Pueblo"},{"id":"o3","texto":"Asociaciones que protegen el ambiente"},{"id":"o4","texto":"Solo el intendente del municipio"},{"id":"o5","texto":"Solo las empresas del lugar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La Constitución abre la puerta a los afectados, al Defensor del Pueblo y a las asociaciones ambientales."}},{"slug":"comunidad-2.s4.p12","orden":12,"grupo":"comunidad-2.s4.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un presupuesto participativo, ¿qué propuesta suele tener más chances de ser elegida y concretada?","opciones":[{"id":"o1","texto":"Una concreta, con costo estimado y apoyos"},{"id":"o2","texto":"Una idea general de mejorar todo el barrio"},{"id":"o3","texto":"La más cara posible, para que se note"},{"id":"o4","texto":"Una presentada el último día sin detalles"}]},"solucion":{"clave":["o1"],"explicacion":"Las propuestas concretas, factibles y con apoyo vecinal son las que más avanzan.","por_opcion":{"o3":"Un costo muy alto suele dejarla fuera del presupuesto disponible."}}},{"slug":"comunidad-2.s4.p13","orden":13,"grupo":"comunidad-2.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje en un grupo vecinal y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Hay una audiencia pública sobre el nuevo relleno; inscribámonos."},{"id":"s2","texto":"No sirve ir, porque la audiencia no decide nada."},{"id":"s3","texto":"Podemos llevar datos sobre la napa y proponer otra ubicación."},{"id":"s4","texto":"Solo los abogados pueden presentar un amparo ambiental."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer las herramientas evita resignarse antes de tiempo.","por_opcion":{"s2":"Las opiniones deben ser consideradas y fundamentadas; además quedan registradas y pueden servir después.","s4":"Pueden presentarlo los afectados, el Defensor del Pueblo y asociaciones ambientales, con patrocinio letrado."}}},{"slug":"comunidad-2.s4.p14","orden":14,"grupo":"comunidad-2.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En una audiencia {{0}} cualquiera puede opinar sobre un proyecto; para frenar rápido un daño se puede presentar un {{1}} ambiental.","banco":[{"id":"w1","texto":"pública"},{"id":"w2","texto":"amparo"},{"id":"w3","texto":"privada"},{"id":"w4","texto":"reclamo"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos herramientas de participación, en una sola línea."}}]},{"slug":"comunidad-2.s5","orden":5,"tipo":"leccion","titulo_es":"Educar y conectar con el mundo","bajada_es":"La Ley de Educación Ambiental Integral y los Objetivos de Desarrollo Sostenible: del aula y el barrio a la agenda global.","minutos":9,"pasos":[{"slug":"comunidad-2.s5.p1","orden":1,"grupo":"comunidad-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Educación Ambiental Integral","cuerpo":["En 2021 se sancionó la Ley 27.621 de Educación Ambiental Integral, que establece que la educación ambiental es un derecho y debe estar presente en todos los niveles y modalidades de la educación, de forma transversal, y también en espacios no formales.","La educación ambiental integral no es solo aprender datos: busca comprender los sistemas, valorar la diversidad, pensar críticamente y participar."]},"solucion":{}},{"slug":"comunidad-2.s5.p2","orden":2,"grupo":"comunidad-2.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué busca la educación ambiental integral? Marcá todo.","opciones":[{"id":"o1","texto":"Comprender cómo funcionan los sistemas naturales y sociales"},{"id":"o2","texto":"Pensar críticamente"},{"id":"o3","texto":"Participar en la comunidad"},{"id":"o4","texto":"Valorar la diversidad biológica y cultural"},{"id":"o5","texto":"Memorizar datos sin relacionarlos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La educación ambiental integral forma para entender y actuar, no solo para repetir."}},{"slug":"comunidad-2.s5.p3","orden":3,"grupo":"comunidad-2.s5.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La Ley 27.621 establece que la educación ambiental debe estar solo en la materia de biología.","razones":[{"id":"r1","texto":"Porque establece un enfoque transversal en toda la educación"},{"id":"r2","texto":"Porque la ley prohíbe hablar de ambiente en otras materias"},{"id":"r3","texto":"Porque solo aplica a las universidades"}]},"solucion":{"valor":false,"explicacion":"Establece que debe ser transversal: estar presente en todos los niveles, modalidades y áreas, además de en espacios no formales.","clave":["r1"]}},{"slug":"comunidad-2.s5.p4","orden":4,"grupo":"comunidad-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los Objetivos de Desarrollo Sostenible","cuerpo":["En 2015, los países de las Naciones Unidas acordaron la Agenda 2030 con 17 Objetivos de Desarrollo Sostenible (ODS). Incluyen terminar con la pobreza y el hambre, salud, educación, igualdad de género, agua y saneamiento, energía asequible y no contaminante, ciudades sostenibles, producción y consumo responsables, acción por el clima, vida submarina y vida de ecosistemas terrestres, entre otros.","Los ODS muestran que lo ambiental, lo social y lo económico están conectados: no se puede resolver uno ignorando los otros."],"destacado":{"valor":"17 ODS","texto":"forman la Agenda 2030 acordada por los países de las Naciones Unidas en 2015."}},"solucion":{}},{"slug":"comunidad-2.s5.p5","orden":5,"grupo":"comunidad-2.s5.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ODS con un tema que ya viste en el árbol.","izquierda":[{"id":"a1","texto":"ODS 6: Agua limpia y saneamiento"},{"id":"a2","texto":"ODS 7: Energía asequible y no contaminante"},{"id":"a3","texto":"ODS 12: Producción y consumo responsables"},{"id":"a4","texto":"ODS 13: Acción por el clima"}],"derecha":[{"id":"b1","texto":"Rama de Agua"},{"id":"b2","texto":"Rama de Energía"},{"id":"b3","texto":"Ramas de Consumo y Residuos"},{"id":"b4","texto":"El tronco y todas las ramas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El árbol de la Academia y la Agenda 2030 hablan de lo mismo desde lugares distintos."}},{"slug":"comunidad-2.s5.p6","orden":6,"grupo":"comunidad-2.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un proyecto de barrio se conecta con los ODS.","items":[{"id":"i1","texto":"Una escuela arma una huerta con compost"},{"id":"i2","texto":"Reduce los residuos orgánicos que van al relleno"},{"id":"i3","texto":"Produce alimentos y enseña a cultivarlos"},{"id":"i4","texto":"Aporta a los ODS de consumo responsable, hambre cero y educación"},{"id":"i5","texto":"La huerta cumple sola toda la Agenda 2030"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo local suma a lo global. Los ODS sirven para ver esas conexiones."}},{"slug":"comunidad-2.s5.p7","orden":7,"grupo":"comunidad-2.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué ODS aporta más directamente cada acción?","grupos":[{"id":"g1","nombre":"ODS 6 (agua)"},{"id":"g2","nombre":"ODS 11 (ciudades)"},{"id":"g3","nombre":"ODS 15 (vida terrestre)"}],"items":[{"id":"i1","texto":"Reparar las pérdidas de agua de la escuela"},{"id":"i2","texto":"Sumar ciclovías y veredas seguras"},{"id":"i3","texto":"Plantar nativas"},{"id":"i4","texto":"Monitorear la calidad de un arroyo"},{"id":"i5","texto":"Recuperar una plaza abandonada"},{"id":"i6","texto":"Proteger un bosque nativo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Muchas acciones aportan a varios ODS a la vez: esa es la idea de su integración."}},{"slug":"comunidad-2.s5.p8","orden":8,"grupo":"comunidad-2.s5.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué muestra que los 17 ODS se pensaron juntos?","opciones":[{"id":"o1","texto":"Que ambiente, sociedad y economía se conectan"},{"id":"o2","texto":"Que cada país elige un solo objetivo"},{"id":"o3","texto":"Que el ambiente importa más que la pobreza"},{"id":"o4","texto":"Que son 17 temas separados sin relación"}]},"solucion":{"clave":["o1"],"explicacion":"Por ejemplo, el acceso a agua segura mejora la salud, la educación y la igualdad de género al mismo tiempo.","por_opcion":{"o3":"Los ODS los ponen en el mismo nivel: se refuerzan entre sí."}}},{"slug":"comunidad-2.s5.p9","orden":9,"grupo":"comunidad-2.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Agenda 2030 se acordó en 2015. Si estamos en 2025, ¿cuántos años quedan para su meta de 2030?","unidad":"años","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"2030 − 2025 = 5 años. Pocos años para metas muy ambiciosas: por eso importa cada acción, desde lo local."}},{"slug":"comunidad-2.s5.p9.v2","orden":9,"grupo":"comunidad-2.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La Agenda 2030 se acordó en 2015. Si estamos en 